style.css:
@-moz-document domain("roblox.com") {
body, html {
    background: url("https://i.imgur.com/fQQPmWW.jpeg") center/cover fixed no-repeat !important;
  }

  /* Quita fondos blancos de Roblox */
  .app-container,
  #app,
  .content,
  .container-main,
  .game-main-content,
  .rbx-body,
  .navigation-container {
    background: transparent !important;
  }
}

@-moz-document domain("roblox.com") {
#app, body {
    background-color: transparent !important;
  }
}
